                r[best_i:best_j + 1] = list(reversed(r[best_i:best_j + 1]))
                improved = True

    # Final cleanup: ensure each customer appears exactly once and capacity feasibility
    seen = set()
    final_routes = []
    for r in routes:
        nr = []
        load = 0
        for c in r:
            if c == depot or c in seen:
                continue
            d = demands[c]
            if load + d <= cap:
                nr.append(c)
                load += d
                seen.add(c)
        if nr:
            final_routes.append(nr)

    missing = []
    for c in customers:
        if c not in seen:
            missing.append(c)

    for c in missing:
        placed = False
        d = demands[c]
        best_r = -1
        best_pos = -1
        best_key = None
        for r_idx, r in enumerate(final_routes):
            if route_load(r) + d > cap:
                continue
            for pos in range(len(r) + 1):
                prev = depot if pos == 0 else r[pos - 1]
                nxt = depot if pos == len(r) else r[pos]
                delta = dist(prev, c) + dist(c, nxt) - dist(prev, nxt)
                key = (delta, len(r), pos, r_idx)
                if best_key is None or key < best_key:
                    best_key = key
                    best_r = r_idx
                    best_pos = pos
        if best_r == -1:
            final_routes.append([c])
        else:
            final_routes[best_r].insert(best_pos, c)

    return final_routes
